// Frequency Counting using std::map
std::map<std::string, int> counts;

// Key 'A' does not exist. Default int (0) is inserted, then incremented.
counts["apple"]++;    // apple: 1

// Key 'B' inserted and incremented.
counts["banana"]++;   // banana: 1

// Key 'apple' exists. Increment value (1 -> 2).
counts["apple"]++;    // apple: 2

// Accessing count
int apple_count = counts["apple"]; // 2

// Zero Initialization for missing keys (accessing via [])
int missing_count = counts["zebra"]; // Inserts "zebra": 0, returns 0
int current_size = counts.size();   // Size increases due to [] access
counts["zebra"]++;                  // zebra: 1
